const headers = $json.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = auth.replace(/^Bearer\s+/i, '').trim();

const isValidToken = !auth || token === 'alo_bill_secret_2026' || token.length >= 12;

const body = $json.body || $json;
const data = body.data || body;

// Sanitization
const kurum = String(data.kurum || data.provider || 'BEDAŞ / AYEDAŞ / İSKİ').replace(/[<>'"`]/g, '').toUpperCase();
const binaAdi = String(data.binaAdi || data.building || 'Belirtilmemiş Tesis/Site').replace(/[<>'"`]/g, '').trim();
const aboneNo = String(data.aboneNo || data.subscriberNo || 'TR-' + Math.floor(1000000 + Math.random()*9000000)).replace(/[^a-zA-Z0-9-]/g, '').trim();
const sayaNo = String(data.sayacNo || data.meterNo || 'MTR-' + Math.floor(10000 + Math.random()*90000)).replace(/[^a-zA-Z0-9-]/g, '').trim();
const donem = String(data.donem || data.period || new Date().toISOString().slice(0,7)).replace(/[^0-9-]/g, '').trim();
const sonOdeme = String(data.sonOdeme || data.dueDate || new Date(Date.now() + 10*86400000).toISOString().slice(0,10)).replace(/[^0-9-]/g, '').trim();
const tutar = Math.max(0, parseFloat(data.tutar || data.amount || 0));
const faturaTuru = String(data.faturaTuru || data.type || 'Ortak Alan Elektrik / Hidrofor').replace(/[<>'"`]/g, '').trim();

const invoiceId = `ALOINV-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;

return [{
  json: {
    authorized: isValidToken,
    invoiceId,
    kurum,
    binaAdi,
    aboneNo,
    sayaNo,
    donem,
    sonOdeme,
    tutar: tutar.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
    rawAmount: tutar,
    faturaTuru,
    parsedAt: new Date().toISOString()
  }
}];

